#!/usr/bin/env python3
"""Generate LF bench programs stressing reactor-uc scaling."""
import pathlib, sys

TEMPLATE = """target uC
// GENERATED by benchmarks/scaling/gen.py -- do not edit.
@platform("native")
@timeout(2 msec)
@fast(true)
main reactor {
  timer t(0, 1 msec)
  state x: int = 0
%(reactions)s}
"""

def emit(n: int) -> str:
    body = "".join("  reaction(t) {= self->x++; =}\n" for _ in range(n))
    return TEMPLATE % {"n": n, "reactions": body}

# Currently, this script generates a single LF file with increasing numbers 
# of reactions stressing only the reaction queue. In the future, we may want 
# to generate multiple LF files with different characteristics, such as 
# different numbers of timers, triggers, and reactions, to stress different 
# parts of the runtime system.
if __name__ == "__main__":
    out = pathlib.Path(sys.argv[1] if len(sys.argv) > 1 else ".")
    out.mkdir(parents=True, exist_ok=True)
    for n in [int(x) for x in (sys.argv[2:] or ["2", "32", "256", "1024"])]:
        p = out / ("Scaling%d.lf" % n)
        p.write_text(emit(n))
        print(p)
